def exact(actual, expected, label):
    if json.dumps(actual, sort_keys=True, default=lambda b: ["bytes", b.hex()]) != json.dumps(expected, sort_keys=True, default=lambda b: ["bytes", b.hex()]):
        raise ValueError(label)

def sha(content):
    return hashlib.sha256(content).hexdigest()

def safe_relative(rel):
    if type(rel) is not str or not rel or '\\' in rel or rel.startswith('/') or any(x in ('', '.', '..') for x in rel.split('/')):
        raise ValueError('unsafe relative path')
    return Path(rel)

def safe_file(root, rel):
    p = root / safe_relative(rel)
    if not p.is_file() or p.is_symlink() or p.absolute() != p.resolve() or not p.resolve().is_relative_to(root.resolve()):
        raise ValueError('unsafe file ' + rel)
    return p.read_bytes()

def validate_confirmation(c,receipt):
    exact(sha((json.dumps(c,ensure_ascii=False,sort_keys=True,indent=2)+'\n').encode()),CONFIRMATION_SHA256,'external324 confirmation')
    exact(sorted(receipt),['encoding','original_display_sha256','original_display_size_bytes','text'],'receipt fields')
    exact(receipt['encoding'],'utf8-json-text','receipt encoding');raw=receipt['text'].encode()
    exact(sha(raw),RECEIPT_SHA256,'original324 digest');exact(len(raw),59061,'original324 length')
    exact(receipt['original_display_sha256'],RECEIPT_SHA256,'receipt digest metadata');exact(receipt['original_display_size_bytes'],59061,'receipt size metadata')
    lines=receipt['text'].splitlines();exact(sum(x.startswith('PASS: ') for x in lines),797,'complete797 return');exact(lines.count('Result: PASS (797 passes, 0 failures)'),1,'full797 summary')
    log='92168f5 (HEAD -> main, origin/main, origin/HEAD) Phase 1 step 324: review continuous guards original baseline and approved phase deltas'
    exact(lines.count(log),2,'matching324 HEAD origin')
    if '[main 92168f5]' not in receipt['text'] or '32fbfba..92168f5  main -> main' not in receipt['text']:raise ValueError('missing324 commit/push')
    return True

def verify_history(root, policy):
    binding = policy['baseline_sha256_bindings']
    serialized = (json.dumps(binding, ensure_ascii=False, sort_keys=True, indent=2)+'\n').encode()
    exact(sha(serialized),BASELINE_JSON_SHA256,'exact accepted1503 manifest')
    exact(len(binding),1503,'accepted1503 file count')
    history = {}
    for rel,digest in binding.items():
        content = safe_file(root,rel)
        if rel == 'CHANGELOG.md':
            prefix = CHANGELOG_PREFIX.encode()
            exact(len(content),policy['accepted_changelog_size_bytes']+len(prefix),'additive CHANGELOG length')
            exact(content[:len(prefix)],prefix,'new CHANGELOG prefix')
            content = content[len(prefix):]
        exact(sha(content),digest,'accepted artifact drift '+rel)
        history[rel] = content
    return history

def validate_design(design,prior,frozen,history):
    exact(design,DESIGN_SPEC,'exact transitive effect graph contract')
    exact(sha((json.dumps(prior,ensure_ascii=False,sort_keys=True,indent=2)+'\n').encode()),PRIOR_DESIGN_SHA256,'exact324 guarded phase contract')
    for step,binding in design['previous_design_bindings'].items():exact(sha(history[binding['path']]),binding['sha256'],'exact prior design '+step)
    exact(design['seven_requirements_bindings'],frozen['seven_review_bindings'],'seven frozen requirements');exact(design['preserved_cross_obligations'],frozen['proof_obligations'],'ten frozen cross obligations')
    binding=design['reference_review_binding'];exact(sha(history[binding['path']]),binding['sha256'],'exact310 reference requirements')
    review=json.loads(history[binding['path']]);raw=history[design['reference_path']];exact(reference_census(raw),design['reference_census'],'complete static header segment census')
    lines=raw.decode().splitlines(keepends=True)
    for name,spec in review['reference_facts']['function_slices'].items():exact(sha(''.join(lines[spec['start_line']-1:spec['end_line']]).encode()),spec['sha256'],'exact eighteen reviewed slices '+name)
    exact(design['nested_argv_contract'],review['adapter_requirements']['exact_argv_allowlist'],'exact nested caller argv')
    return True

def validate_tables(roadmap, obligations):
    exact(sha(roadmap),TABLE_HASHES[0],'exact typed roadmap')
    exact(sha(obligations),TABLE_HASHES[1],'exact obligation coverage table')
    return True

def canonical(value):
    return json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=True).encode('ascii')

def unique_pairs(pairs):
    result={}
    for key,value in pairs:
        if key in result:raise ValueError('duplicate JSON field')
        result[key]=value
    return result


def reference_census(raw):
    text=raw.decode();lines=text.splitlines(keepends=True)
    starts=[(i,m.group(1)) for i,line in enumerate(lines) if (m:=re.fullmatch(r'([A-Za-z_][A-Za-z_0-9]*)\(\) \{\n',line))]
    entry=next(i for i,line in enumerate(lines) if line.startswith('if [ "${BASH_SOURCE[0]}" = "$0" ]; then'))
    rows=[]
    for index,(begin,name) in enumerate(starts):
        end=starts[index+1][0] if index+1<len(starts) else entry
        chunk=''.join(lines[begin:end]).encode()
        category='unclassified-function-requires-transitive-helper-review'
        if re.search(r'boot|initrd|grub|kernel',name):category='boot-GenInitrd-kernel-potential-reads-and-effects'
        elif re.search(r'sbo|sqg|elf|flatpak|cinnamon|abi',name):category='optional-module-potential-effects-not-excluded-by-flags-alone'
        elif re.search(r'json|print|emit|log|banner|summary',name):category='stream-FD-log-and-publication-surface'
        elif re.search(r'config|runtime|snapshot|cleanup|lock|trap',name):category='owned-file-config-lock-trap-and-snapshot-surface'
        if name in ['main','run_apply_workflow','update_slackware_system']:category='whole-entry-and-nested-caller-effect-surface'
        rows.append(dict(name=name,start_line=begin+1,end_line=end,sha256=sha(chunk),classification=category,status='static-segment-bound-not-operationally-closed'))
    if len(rows)!=len({r['name'] for r in rows}):raise ValueError('duplicate static function header')
    return dict(reference_sha256=sha(raw),line_count=len(lines),function_count=len(rows),functions=rows,
        prelude_sha256=sha(''.join(lines[:starts[0][0]]).encode()),entry_tail_sha256=sha(''.join(lines[entry:]).encode()),
        method='exact-column-zero-function-header-segments-not-Bash-AST-or-sound-call-graph',actual_transitive_graph_complete=False)

def evaluate_private_graph_node(value):
    exact(sorted(value),['conditions','node','origin','scope'],'graph node fields');exact(value['origin'],'synthetic-private-fixture','graph node origin')
    exact(value['scope'],'transitive-effect-contract-only','graph node scope');exact(sorted(value['conditions']),sorted(GATE_KEYS),'graph node gates')
    if any(type(x) is not bool for x in value['conditions'].values()):raise ValueError('typed graph proof conditions')
    if type(value['node']) is not str or value['node'] not in NODE_GATES:raise ValueError('unknown graph node')
    conditions=value['conditions'];eligible=all(conditions[k] for k in NODE_GATES[value['node']])
    if value['node'] in FORBIDDEN_DISPATCH_NODES:eligible=False
    return dict(model_node_contract_eligible=eligible,actual_dispatch_authorized=False,actual_transitive_graph_proven=False,
        actual_grant_consumed=False,actual_operational_conformance=False,actual_host_obligations_closed=False)

def simulate_private_nested_calls(value):
    exact(sorted(value),['calls','conditions','origin','scope'],'nested model fields');exact(value['origin'],'synthetic-private-fixture','nested origin')
    exact(value['scope'],'raw-selector-status-and-persistent-latch-contract-only','nested scope');exact(sorted(value['conditions']),sorted(SELECTOR_GATES),'nested gates')
    if any(type(x) is not bool for x in value['conditions'].values()):raise ValueError('typed nested proof conditions')
    if type(value['calls']) is not list or len(value['calls'])>12:raise ValueError('bounded nested calls')
    latched=False;trace=[];original_status=None;allowed_count=0
    for call in value['calls']:
        exact(sorted(call),sorted(['action','argv','effects','inputs','raw_status','raw_pkglist_sha256','selectors','stderr_error','stdout_error']),'nested call fields')
        action=call['action']
        if type(action) is not str or action not in ['update','install-new','upgrade-all','unreviewed-reference-effect']:raise ValueError('typed nested action')
        if type(call['raw_status']) is not int or call['raw_status'] not in [-1,0,1,2,20]:raise ValueError('typed raw nested status')
        if type(call['stdout_error']) is not bool or type(call['stderr_error']) is not bool:raise ValueError('typed stream guards')
        exact(type(call['argv']).__name__,'list','typed argv');exact(type(call['selectors']).__name__,'dict','typed selector vectors')
        allowed=not latched and all(value['conditions'].values()) and action in CALL_ARGV and call['argv']==CALL_ARGV.get(action)
        allowed=allowed and call['inputs']==SELECTOR_INPUTS and call['selectors']==SELECTOR_VECTORS and call['raw_pkglist_sha256']==FIXTURE_RAW_PIN
        allowed=allowed and not call['stdout_error'] and not call['stderr_error'] and call['effects']==CALL_EFFECTS.get(action)
        if action=='install-new':allowed=allowed and call['raw_status'] in [0,20]
        else:allowed=allowed and call['raw_status']==0
        if allowed:allowed_count+=1
        else:
            latched=True
            if original_status is None:original_status=call['raw_status']
        trace.append(dict(action=action,raw_status=call['raw_status'],model_contract_satisfied=allowed,forward_latched=latched,original_failure_raw_status=original_status))
    return dict(trace=trace,model_satisfied_call_count=allowed_count,model_original_failure_raw_status=original_status,
        actual_selector_equivalence_proven=False,actual_package_effect_proven=False,actual_dispatch_authorized=False,
        actual_grant_consumed=False,actual_operational_conformance=False,actual_host_obligations_closed=False,retry_authorized=False)

def simulate_private_publication(value):
    exact(sorted(value),['conditions','events','origin','scope'],'publication model fields');exact(value['origin'],'synthetic-private-fixture','publication origin')
    exact(value['scope'],'closed-captured-data-and-last-receipt-contract-only','publication scope');exact(sorted(value['conditions']),sorted(PUBLICATION_GATES),'publication gates')
    if any(type(x) is not bool for x in value['conditions'].values()):raise ValueError('typed publication proof conditions')
    if type(value['events']) is not list or len(value['events'])>24:raise ValueError('bounded publication events')
    progress=0;latched=not all(value['conditions'].values());unknown=False;denied=0;trace=[]
    for event in value['events']:
        if type(event) is not str or event not in PUBLICATION_EVENTS+PUBLICATION_FAILURES:raise ValueError('typed publication event')
        if latched:denied+=1
        elif event in PUBLICATION_FAILURES:latched=True;unknown=event in ['record-outcome-unknown','receipt-outcome-unknown','handoff-outcome-unknown']
        elif progress<len(PUBLICATION_EVENTS) and event==PUBLICATION_EVENTS[progress]:progress+=1
        else:latched=True;denied+=1
        trace.append(dict(progress=progress,latched=latched,record_visible=progress>=4,last_receipt_visible=progress>=6))
    return dict(trace=trace,model_publication_complete=progress==len(PUBLICATION_EVENTS) and not latched,
        model_controller_obligations_pending=progress!=len(PUBLICATION_EVENTS) or latched,
        model_receipt_durability=None if unknown else progress>=7,model_artifacts_preserved=progress>=4,model_denials=denied,
        actual_publication_or_receipt_proven=False,actual_target_closure_proven=False,actual_dispatch_authorized=False,
        actual_host_obligations_closed=False,actual_operational_conformance=False,actual_strong_safe_pause_confirmed=False,
        replay_authorized=False,target_refresh_authorized=False)






def run_historical(history):
    with tempfile.TemporaryDirectory(prefix='step325-exact324-') as directory:
        snapshot = Path(directory)/'slack-update'
        for rel,content in history.items():
            p = snapshot/safe_relative(rel); p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(content)
        result = subprocess.run(['bash',str(snapshot/'tests/reference'/('test-'+PRIOR+'-harness.sh'))],capture_output=True)
        lines = result.stdout.decode().splitlines()
        if result.returncode or lines.count('Result: PASS (797 passes, 0 failures)')!=1 or sum(x.startswith('PASS: ') for x in lines)!=797:
            sys.stderr.buffer.write(result.stdout+result.stderr)
            raise ValueError('full exact797 predecessor acceptance failed')
        return result.stdout

def main(root,out):
    if not root.is_dir() or root.absolute()!=root.resolve():raise ValueError('unsafe repository root')
    for rel,digest in OWN_HASHES.items():exact(sha(safe_file(root,rel)),digest,'changed325 input '+rel)
    fixture=root/FIXTURE;load=lambda suffix:json.loads((fixture/(BASE+suffix)).read_bytes())
    policy,design=load('-policy.json'),load('-design.json');history=verify_history(root,policy)
    frozen=json.loads(history[FIXTURE+'/'+REQUIREMENTS_BASE+'-freeze.json']);prior=json.loads(history[FIXTURE+'/'+PRIOR+'-design.json'])
    validate_design(design,prior,frozen,history);validate_confirmation(load('-checkpoint-confirmation.json'),load('-step324-user-acceptance.json'))
    validate_tables(*[(fixture/(BASE+s)).read_bytes() for s in ['-transitive-effect-contract.tsv','-reference-source-census.tsv']])
    payloads={BASE+s:(fixture/(BASE+s)).read_bytes() for s in SUFFIXES};log_name=BASE+'-predecessor-test.log'
    if not out.is_dir() or out.absolute()!=out.resolve():raise ValueError('output must exist without symlink ancestors')
    if any((out/name).exists() or (out/name).is_symlink() for name in list(payloads)+[log_name]):raise ValueError('occupied output; no overwrite')
    payloads[log_name]=run_historical(history);exact(verify_history(root,policy),history,'history changed during validation')
    for rel,digest in OWN_HASHES.items():exact(sha(safe_file(root,rel)),digest,'325 input changed during validation')
    created=[]
    try:
        for name,content in payloads.items():
            with (out/name).open('xb') as stream:created.append(out/name);stream.write(content)
    except BaseException:
        for p in reversed(created):p.unlink()
        raise
    print('exact_step324_acceptance\tPASS (797 passes, 0 failures)')
    print('step325_transitive_effect_graph_design_review_status\tPASS');print('actual_transitive_graph_or_selector_proven\tno')
    print('actual_dispatch_or_publication_authorized\tno');print('operational_readiness\tno');print('strong_safe_pause\tno')
    print('last_confirmed_strong_safe_pause_step\t318');print('next_stage_authorized\tno')

if __name__ == '__main__':
    try: main(Path(sys.argv[1]).absolute(),Path(sys.argv[2]).absolute())
    except (ValueError,OSError,KeyError,TypeError) as exc:
        print('ERROR: '+str(exc),file=sys.stderr);sys.exit(1)
